import logging, math, os, time
from . import shaper_calibrate
from .creality_config import *

class TestAxis:

    def __init__(self, axis=None, vib_dir=None):
        if axis is None:
            self._name = "axis=%.3f,%.3f" % (vib_dir[0], vib_dir[1])
        else:
            self._name = axis
        if vib_dir is None:
            self._vib_dir = (1.0, 0.0) if axis == "x" else (0.0, 1.0)
        else:
            s = math.sqrt(sum([d * d for d in vib_dir]))
            self._vib_dir = [d / s for d in vib_dir]

    def matches(self, chip_axis):
        if self._vib_dir[0]:
            if "x" in chip_axis:
                return True
            if self._vib_dir[1]:
                if "y" in chip_axis:
                    return True
            return False

    def get_name(self):
        return self._name

    def get_point(self, l):
        return (
         self._vib_dir[0] * l, self._vib_dir[1] * l)


def _parse_axis(gcmd, raw_axis):
    if raw_axis is None:
        return
    raw_axis = raw_axis.lower()
    if raw_axis in ('x', 'y'):
        return TestAxis(axis=raw_axis)
    dirs = raw_axis.split(",")
    if len(dirs) != 2:
        raise gcmd.error("Invalid format of axis '%s'" % (raw_axis,))
    try:
        dir_x = float(dirs[0].strip())
        dir_y = float(dirs[1].strip())
    except:
        raise gcmd.error("Unable to parse axis direction '%s'" % (raw_axis,))
    else:
        return TestAxis(vib_dir=(dir_x, dir_y))


class VibrationPulseTest:

    def __init__(self, config):
        self.printer = config.get_printer()
        self.gcode = self.printer.lookup_object("gcode")
        self.min_freq = config.getfloat("min_freq", 5.0, minval=1.0)
        self.max_freq = config.getfloat("max_freq", 133.33333333333334, minval=(self.min_freq),
          maxval=300.0)
        self.accel_per_hz = config.getfloat("accel_per_hz", 75.0, above=0.0)
        self.hz_per_sec = config.getfloat("hz_per_sec", 1.0, minval=0.1,
          maxval=2.0)
        self.probe_points = config.getlists("probe_points", seps=(',', '\n'), parser=float,
          count=3)

    def get_start_test_points(self):
        return self.probe_points

    def prepare_test(self, gcmd):
        self.freq_start = gcmd.get_float("FREQ_START", (self.min_freq), minval=1.0)
        self.freq_end = gcmd.get_float("FREQ_END", (self.max_freq), minval=(self.freq_start),
          maxval=300.0)
        self.hz_per_sec = gcmd.get_float("HZ_PER_SEC", (self.hz_per_sec), above=0.0,
          maxval=2.0)

    def run_test(self, axis, gcmd):
        toolhead = self.printer.lookup_object("toolhead")
        (X, Y, Z, E) = toolhead.get_position()
        sign = 1.0
        freq = self.freq_start
        systime = self.printer.get_reactor().monotonic()
        toolhead_info = toolhead.get_status(systime)
        old_max_accel = toolhead_info["max_accel"]
        old_minimum_cruise_ratio = toolhead_info["minimum_cruise_ratio"]
        max_accel = self.freq_end * self.accel_per_hz
        self.gcode.run_script_from_command("SET_VELOCITY_LIMIT ACCEL=%.3f MINIMUM_CRUISE_RATIO=0" % (
         max_accel,))
        input_shaper = self.printer.lookup_object("input_shaper", None)
        if input_shaper is not None and not gcmd.get_int("INPUT_SHAPING", 0):
            input_shaper.disable_shaping()
            gcmd.respond_info("Disabled [input_shaper] for resonance testing")
        else:
            input_shaper = None
        gcmd.respond_info("Testing frequency %.0f Hz" % (freq,))
        while True:
            if not freq <= self.freq_end + 1e-06:
                t_seg = 0.25 / freq
                accel = self.accel_per_hz * freq
                max_v = accel * t_seg
                toolhead.cmd_M204(self.gcode.create_gcode_command("M204", "M204", {"S": accel}))
                L = 0.5 * accel * t_seg ** 2
                (dX, dY) = axis.get_point(L)
                nX = X + sign * dX
                nY = Y + sign * dY
                toolhead.move([nX, nY, Z, E], max_v)
                toolhead.move([X, Y, Z, E], max_v)
                sign = -sign
                old_freq = freq
                freq += 2.0 * t_seg * self.hz_per_sec
                if math.floor(freq) > math.floor(old_freq):
                    gcmd.respond_info("Testing frequency %.0f Hz" % (freq,))

        self.gcode.run_script_from_command("SET_VELOCITY_LIMIT ACCEL=%.3f MINIMUM_CRUISE_RATIO=%.3f" % (
         old_max_accel, old_minimum_cruise_ratio))
        if input_shaper is not None:
            input_shaper.enable_shaping()
            gcmd.respond_info("Re-enabled [input_shaper]")

    def get_max_freq(self):
        return self.freq_end


class ResonanceTester:

    def __init__(self, config):
        self.printer = config.get_printer()
        self.move_speed = config.getfloat("move_speed", 50.0, above=0.0)
        fs = self.printer.get_features()
        same_sensor = fs.has_set(INPUT_SHAPER_SHARE_SENSOR)
        self.axis_x_use_y = config.getboolean("axis_x_use_y", same_sensor)
        self.test = VibrationPulseTest(config)
        if not config.get("accel_chip_x", None):
            self.accel_chip_names = [
             (
              "xy", config.get("accel_chip").strip())]
        else:
            self.accel_chip_names = [
             (
              "x", config.get("accel_chip_x").strip()),
             (
              "y", config.get("accel_chip_y").strip())]
            if self.accel_chip_names[0][1] == self.accel_chip_names[1][1]:
                self.accel_chip_names = [
                 (
                  "xy", self.accel_chip_names[0][1])]
        self.max_smoothing = config.getfloat("max_smoothing", None, minval=0.05)
        self.gcode = self.printer.lookup_object("gcode")
        self.gcode.register_command("MEASURE_AXES_NOISE", (self.cmd_MEASURE_AXES_NOISE),
          desc=(self.cmd_MEASURE_AXES_NOISE_help))
        self.gcode.register_command("TEST_RESONANCES", (self.cmd_TEST_RESONANCES),
          desc=(self.cmd_TEST_RESONANCES_help))
        self.gcode.register_command("SHAPER_CALIBRATE", (self.cmd_SHAPER_CALIBRATE),
          desc=(self.cmd_SHAPER_CALIBRATE_help))
        self.printer.register_event_handler("klippy:connect", self.connect)

    def connect(self):
        self.accel_chips = [(
         chip_axis, self.printer.lookup_object(chip_name)) for chip_axis, chip_name in self.accel_chip_names]

    def _run_test(self, gcmd, axes, helper, raw_name_suffix=None, accel_chips=None, test_point=None):
        toolhead = self.printer.lookup_object("toolhead")
        calibration_data = {axis: None for axis in axes}
        self.test.prepare_test(gcmd)
        if test_point is not None:
            test_points = [
             test_point]
        else:
            test_points = self.test.get_start_test_points()
        for point in test_points:
            toolhead.manual_move(point, self.move_speed)
            if len(test_points) > 1 or test_point is not None:
                gcmd.respond_info("Probing point (%.3f, %.3f, %.3f)" % tuple(point))
            else:
                for axis in axes:
                    toolhead.wait_moves()
                    toolhead.dwell(0.5)
                    if len(axes) > 1:
                        gcmd.respond_info("Testing axis %s" % axis.get_name())
                    raw_values = []
                    if accel_chips is None:
                        for (chip_axis, chip) in self.accel_chips:
                            if axis.matches(chip_axis):
                                aclient = chip.start_internal_client()
                                raw_values.append((chip_axis, aclient, chip.name))

                    else:
                        for chip in accel_chips:
                            aclient = chip.start_internal_client()
                            raw_values.append((axis, aclient, chip.name))

                    self.test.run_test(axis, gcmd)
                    for (chip_axis, aclient, chip_name) in raw_values:
                        aclient.finish_measurements()
                        if raw_name_suffix is not None:
                            raw_name = self.get_filename("raw_data", raw_name_suffix, axis, point if len(test_points) > 1 else None, chip_name if accel_chips is not None else None)
                            aclient.write_to_file(raw_name)
                            gcmd.respond_info("Writing raw accelerometer data to %s file" % (
                             raw_name,))

                    if helper is None:
                        pass
                    else:
                        for (chip_axis, aclient, chip_name) in raw_values:
                            if not aclient.has_valid_samples():
                                raise gcmd.error("accelerometer '%s' measured no data" % (
                                 chip_name,))
                            else:
                                new_data = helper.process_accelerometer_data(aclient)
                            if calibration_data[axis] is None:
                                calibration_data[axis] = new_data
                            else:
                                calibration_data[axis].add_data(new_data)

                    return calibration_data

    def _parse_chips(self, accel_chips):
        parsed_chips = []
        for chip_name in accel_chips.split(","):
            if "adxl345" in chip_name:
                chip_lookup_name = chip_name.strip()
            else:
                chip_lookup_name = "adxl345 " + chip_name.strip()
            chip = self.printer.lookup_object(chip_lookup_name)
            parsed_chips.append(chip)

        return parsed_chips

    def _find_chips_name(self, accel_chips):
        parsed_chips = []
        for (a, pre_chip) in self.accel_chip_names:
            chip_segs = pre_chip.split(" ")
            if len(chip_segs) > 1:
                parsed_chips.append(chip_segs[-1])
            else:
                parsed_chips.append(pre_chip)

        return parsed_chips

    def _get_max_calibration_freq(self):
        return 1.5 * self.test.get_max_freq()

    cmd_TEST_RESONANCES_help = "Runs the resonance test for a specifed axis"

    def cmd_TEST_RESONANCES(self, gcmd):
        axis = _parse_axis(gcmd, gcmd.get("AXIS").lower())
        chips_str = gcmd.get("CHIPS", None)
        test_point = gcmd.get("POINT", None)
        if test_point:
            test_coords = test_point.split(",")
            if len(test_coords) != 3:
                raise gcmd.error("Invalid POINT parameter, must be 'x,y,z'")
            try:
                test_point = [float(p.strip()) for p in test_coords]
            except ValueError:
                raise gcmd.error("Invalid POINT parameter, must be 'x,y,z' where x, y and z are valid floating point numbers")
            else:
                accel_chips = self._parse_chips(chips_str) if chips_str else None
                outputs = gcmd.get("OUTPUT", "resonances").lower().split(",")
                for output in outputs:
                    if output not in ('resonances', 'raw_data'):
                        raise gcmd.error("Unsupported output '%s', only 'resonances' and 'raw_data' are supported" % (
                         output,))

                if not outputs:
                    raise gcmd.error("No output specified, at least one of 'resonances' or 'raw_data' must be set in OUTPUT parameter")
                name_suffix = gcmd.get("NAME", time.strftime("%Y%m%d_%H%M%S"))
                if not self.is_valid_name_suffix(name_suffix):
                    raise gcmd.error("Invalid NAME parameter")
                csv_output = "resonances" in outputs
                raw_output = "raw_data" in outputs
                if csv_output:
                    helper = shaper_calibrate.ShaperCalibrate(self.printer)
                else:
                    helper = None
                data = self._run_test(gcmd,
                  [axis], helper, raw_name_suffix=(name_suffix if raw_output else None),
                  accel_chips=accel_chips,
                  test_point=test_point)[axis]
                if csv_output:
                    csv_name = self.save_calibration_data("resonances",
                      name_suffix, helper, axis, data, point=test_point,
                      max_freq=(self._get_max_calibration_freq()))
                    gcmd.respond_info("Resonances data written to %s file" % (csv_name,))

    cmd_SHAPER_CALIBRATE_help = "Simular to TEST_RESONANCES but suggest input shaper config"

    def cmd_SHAPER_CALIBRATE(self, gcmd):
        axis = gcmd.get("AXIS", None)
        apply_x_from_y = False
        if not axis:
            if self.axis_x_use_y:
                calibrate_axes = [
                 TestAxis("y")]
                apply_x_from_y = True
            else:
                calibrate_axes = [
                 TestAxis("x"), TestAxis("y")]
        elif axis.lower() not in "xy":
            raise gcmd.error("Unsupported axis '%s'" % (axis,))
        else:
            calibrate_axes = [
             TestAxis(axis.lower())]
        chips_str = gcmd.get("CHIPS", None)
        accel_chips = self._parse_chips(chips_str) if chips_str else None
        pre_accel_chips = self._find_chips_name(chips_str)
        max_smoothing = gcmd.get_float("MAX_SMOOTHING",
          (self.max_smoothing), minval=0.05)
        name_suffix = gcmd.get("NAME", time.strftime("%Y%m%d_%H%M%S"))
        if not self.is_valid_name_suffix(name_suffix):
            raise gcmd.error("Invalid NAME parameter")
        input_shaper = self.printer.lookup_object("input_shaper", None)
        helper = shaper_calibrate.ShaperCalibrate(self.printer)
        harmonic_anc = self.printer.lookup_object("harmonic_anc", None)
        ha_enable = False
        if harmonic_anc:
            if harmonic_anc.harmonic_status == 1:
                ha_enable = True
                gcmd.respond_info("disable harmonic")
                self.gcode.run_script_from_command("HARMONIC_OFF SAVE=0")
            accel_chips = None
            for chip_name in pre_accel_chips:
                cmd = "ACCELEROMETER_SET_SAMPLE_RATE CHIP=%s RATE=800" % chip_name
                self.gcode.run_script_from_command(cmd)

        try:
            calibration_data = self._run_test(gcmd, calibrate_axes, helper, accel_chips=accel_chips)
        except gcmd.error as e:
            try:
                self.gcode.run_script_from_command("ACCELEROMETER_SET_SAMPLE_RATE RATE=3200")
                raise e
            finally:
                e = None
                del e

        else:
            for chip_name in pre_accel_chips:
                cmd = "ACCELEROMETER_SET_SAMPLE_RATE CHIP=%s RATE=3200" % chip_name
                self.gcode.run_script_from_command(cmd)

            if ha_enable:
                gcmd.respond_info("enable harmonic")
                self.gcode.run_script_from_command("HARMONIC_ON SAVE=0")
            configfile = self.printer.lookup_object("configfile")
            for axis in calibrate_axes:
                axis_name = axis.get_name()
                gcmd.respond_info("Calculating the best input shaper parameters for %s axis" % (
                 axis_name,))
                calibration_data[axis].normalize_to_frequencies()
                systime = self.printer.get_reactor().monotonic()
                toolhead = self.printer.lookup_object("toolhead")
                toolhead_info = toolhead.get_status(systime)
                scv = toolhead_info["square_corner_velocity"]
                max_freq = self._get_max_calibration_freq()
                (best_shaper, all_shapers) = helper.find_best_shaper((calibration_data[axis]),
                  max_smoothing=max_smoothing, scv=scv,
                  max_freq=max_freq,
                  logger=(gcmd.respond_info))
                gcmd.respond_info("Recommended shaper_type_%s = %s, shaper_freq_%s = %.1f Hz" % (
                 axis_name, best_shaper.name,
                 axis_name, best_shaper.freq))
                if input_shaper is not None:
                    helper.apply_params(input_shaper, axis_name, best_shaper.name, best_shaper.freq)
                    if apply_x_from_y:
                        helper.apply_params(input_shaper, "x", best_shaper.name, best_shaper.freq)
                    helper.save_params(configfile, axis_name, best_shaper.name, best_shaper.freq)
                    if apply_x_from_y:
                        helper.save_params(configfile, "x", best_shaper.name, best_shaper.freq)
                    csv_name = self.save_calibration_data("calibration_data",
                      name_suffix, helper, axis, (calibration_data[axis]),
                      all_shapers, max_freq=max_freq)
                    gcmd.respond_info("Shaper calibration data written to %s file" % (csv_name,))
                gcmd.respond_info("The SAVE_CONFIG command will update the printer config file\nwith these parameters and restart the printer.")

    cmd_MEASURE_AXES_NOISE_help = "Measures noise of all enabled accelerometer chips"

    def cmd_MEASURE_AXES_NOISE(self, gcmd):
        meas_time = gcmd.get_float("MEAS_TIME", 2.0)
        raw_values = [(chip_axis, chip.start_internal_client()) for chip_axis, chip in self.accel_chips]
        self.printer.lookup_object("toolhead").dwell(meas_time)
        for (chip_axis, aclient) in raw_values:
            aclient.finish_measurements()

        helper = shaper_calibrate.ShaperCalibrate(self.printer)
        for (chip_axis, aclient) in raw_values:
            if not aclient.has_valid_samples():
                raise gcmd.error("%s-axis accelerometer measured no data" % (
                 chip_axis,))
            else:
                data = helper.process_accelerometer_data(aclient)
                vx = data.psd_x.mean()
                vy = data.psd_y.mean()
                vz = data.psd_z.mean()
                gcmd.respond_info("Axes noise for %s-axis accelerometer: %.6f (x), %.6f (y), %.6f (z)" % (
                 chip_axis, vx, vy, vz))

    def is_valid_name_suffix(self, name_suffix):
        return name_suffix.replace("-", "").replace("_", "").isalnum()

    def get_filename(self, base, name_suffix, axis=None, point=None, chip_name=None):
        name = base
        if axis:
            name += "_" + axis.get_name()
        if chip_name:
            name += "_" + chip_name.replace(" ", "_")
        if point:
            name += "_%.3f_%.3f_%.3f" % (point[0], point[1], point[2])
        name += "_" + name_suffix
        return os.path.join("/tmp", name + ".csv")

    def save_calibration_data(self, base_name, name_suffix, shaper_calibrate, axis, calibration_data, all_shapers=None, point=None, max_freq=None):
        output = self.get_filename(base_name, name_suffix, axis, point)
        shaper_calibrate.save_calibration_data(output, calibration_data, all_shapers, max_freq)
        return output


def load_config(config):
    return ResonanceTester(config)

